    # Directions for movement (right, down)
    directions = [(0, 1), (1, 0)]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for dx, dy in directions:
                nx, ny = i + dx, j + dy
                if 0 <= nx < N and 0 <= ny < N:
                    dp[nx][ny] = max(dp[nx][ny], dp[i][j] + grid[nx][ny])

    # Return the maximum sum collected on two paths
