def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.

    Args:
    - N (int): The size of the grid (N x N).
    - grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple contains
      the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
      The list is terminated by a tuple with all zeros.

    Returns:
    - int: The maximum sum of values collected on the two paths.
    """
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Place the values from the grid_values list into the grid
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table with negative infinity
    dp = [[-float('inf')] * N for _ in range(N)]

    # Base case: starting point
    dp[0][0] = grid[0][0]

    # Fill the DP table for the first path
    for i in range(N):
        for j in range(N):
            if i > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + grid[i][j])

    # Initialize a second DP table to find the second path
    dp2 = [[-float('inf')] * N for _ in range(N)]

    # Base case: starting point for the second path (skip the first cell)
    dp2[0][0] = dp[0][0]

    # Fill the second DP table
    for i in range(N):
        for j in range(N):
            if i > 0:
                dp2[i][j] = max(dp2[i][j], dp2[i-1][j] + grid[i][j])
            if j > 0:
                dp2[i][j] = max(dp2[i][j], dp2[i][j-1] + grid[i][j])

    # Combine the two paths, ensuring no reuse of values
    max_sum = 0
    for i in range(N):
        for j in range(N):
            for k in range(N):
                for l in range(N):
                    if (i != k or j != l) and (i == k and j == l):
                        continue
                    max_sum = max(max_sum, dp[i][j] + dp2[k][l])

    return max_sum

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create an N x N grid initialized to 0
