        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize a DP table
    dp = [[[-float('inf')] * (N+1) for _ in range(N+1)] for _ in range(N+1)]

    # Base case: starting point
    dp[1][1][1] = grid[0][0]

    # Fill the DP table
    for i in range(1, N+1):
        for j in range(1, N+1):
            for k in range(1, i+j+1):
                if k > i or k > j:
                    continue
                if grid[i-1][j-1] > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k] + grid[i-1][j-1])
