                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k])
                if j > 1:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k])

    # The result is the maximum value collected by two paths
    return dp[N][N][N]

