def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")

    diagonal = 1
    current_position = 1

    while current_position < N:
        diagonal += 1
        current_position += diagonal

    if diagonal % 2 == 0:
        numerator = current_position - diagonal + 1
        denominator = diagonal - (current_position - diagonal) + 1
    else:
        numerator = diagonal - (current_position - diagonal) + 1
        denominator = current_position - diagonal + 1

    return f"{numerator}/{denominator}"

def cantor_numbering(N: int) -> str:
    if not isinstance(N, int) or N < 1:
        raise ValueError("N must be a positive integer")

    k = 1
    while N > k * (k + 1) // 2:
        N -= k * (k + 1) // 2
        k += 1

    row = k - N + 1
    col = N - k * (k - 1) // 2

    if k % 2 == 0:
        return f"{col}/{row}"
    else:
        return f"{row}/{col}"

def cantor_numbering(N: int) -> str:
