    while N > level * (level + 1) // 2:
        N -= level * (level + 1) // 2
        level += 1

    if level % 2 == 0:
        numerator = N
        denominator = level + 1 - N
    else:
        numerator = level + 1 - N
        denominator = N

    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or N <= 0 or K < 0 or K >= N - 1:
        raise ValueError("Invalid input parameters")

    # Convert the number string into an array of integers
    num_list = [int(digit) for digit in num_str]

    # If K is 0, there are no multiplication signs to insert, so return the product of all digits
    if K == 0:
        return prod(num_list)

    # Initialize the maximum product to 0
    max_product = 0

    # Iterate through all possible ways to insert K multiplication signs
    for i in range(1, N):
        for j in range(i + 1, N):
            # Split the number string into three parts and calculate the product
            product = prod(num_list[:i]) * prod(num_list[i:j]) * prod(num_list[j:])
            # Update the maximum product if the current product is greater
            max_product = max(max_product, product)

    return max_product

def max_product(num_str: str, N: int, K: int) -> int:
    def split_and_multiply(parts):
        product = 1
        for part in parts:
            product *= int(part)
        return product

    if not num_str or N != len(num_str) or K < 0 or K > N - 1:
        return 0

    max_product_value = 0
    for i in range(1, K + 2):
        for j in range(i + 1, K + 3):
            parts = [num_str[:i], num_str[i:j], num_str[j:]]
            max_product_value = max(max_product_value, split_and_multiply(parts))

    return max_product_value

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit() or N != len(num_str) or K < 0 or K >= N:
        raise ValueError("Invalid input")

    num_list = [int(digit) for digit in num_str]

    if K == 0:
        return int(''.join(map(str, num_list)))

    max_product = 0
    for i in range(1, K + 1):
        for indices in combinations(range(1, N), i):
            product = 1
            start = 0
            for index in indices:
                product *= int(''.join(map(str, num_list[start:index])))
                start = index
            product *= int(''.join(map(str, num_list[start:])))
            max_product = max(max_product, product)

    return max_product

