        raise ValueError("Grades list must contain exactly two integers.")
    if not isinstance(grades[0], int) or not isinstance(grades[1], int):
        raise ValueError("Elements of grades list must be integers.")
    if not (leader == 'Y' or leader == 'N') or not (west == 'Y' or west == 'N'):
        raise ValueError("Leader and west parameters must be 'Y' or 'N'.")
    if not isinstance(papers, int):
        raise ValueError("Papers must be an integer.")

    final_average, class_evaluation = grades
    scholarship = 0

    if final_average > 80 and papers > 0:
        scholarship += 8000

    if final_average > 85 and class_evaluation > 80:
        scholarship += 4000

    if final_average > 90:
        scholarship += 2000

    if final_average > 85 and west == 'Y':
        scholarship += 1000

    if class_evaluation > 80 and leader == 'Y':
        scholarship += 850

    return scholarship

def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            digit = int(char) if char != 'X' else 10
            total += digit * (10 - i)
        return total % 11

    # Remove hyphens and convert to digits
    clean_isbn = isbn.replace('-', '')
    if len(clean_isbn) != 10:
        raise ValueError("Invalid ISBN length")

    # Calculate the checksum digit
    calculated_checksum = calculate_checksum(clean_isbn[:9])

    # Compare calculated checksum with the provided checksum
    provided_checksum = int(clean_isbn[9]) if clean_isbn[9] != 'X' else 10
    if calculated_checksum != provided_checksum:
        # If incorrect, correct the checksum
        correct_isbn = clean_isbn[:9] + ('X' if calculated_checksum == 10 else str(calculated_checksum))
        return '-'.join([correct_isbn[:3], correct_isbn[3:6], correct_isbn[6:10]])
    else:
        return "Right"

