def verify_isbn(isbn: str) -> str:
    # Check if the ISBN format is correct
    if len(isbn) != 13 or isbn[4] != '-' or isbn[9] != '-':
        raise ValueError("Invalid ISBN format")

    digits = list(isbn.replace('-', ''))

    # Convert the digits to integers, handling 'X' as 10
    try:
        values = [int(d) if d != 'X' else 10 for d in digits]
    except ValueError:
        raise ValueError("ISBN should only contain digits and 'X'")

    # Calculate the ISBN checksum
    checksum = sum((10 - i) * v for i, v in enumerate(values)) % 11

    # Check if the checksum is correct
    if checksum == 0:
        return "Right"
    else:
        # Try to find the correct digit that would make the checksum zero
        for i in range(10):
            values[9] = i
            if sum((10 - j) * values[j] for j in range(10)) % 11 == 0:
                corrected_isbn = isbn[:10] + str(i)
                return corrected_isbn

    return isbn

def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn):
        total = 0
        for i in range(9):
            total += int(isbn[i]) * (10 - i)
        return total % 11

    parts = isbn.replace('-', '')
    if len(parts) != 10 or not parts[:9].isdigit() or parts[9] not in '0123456789X':
        raise ValueError("Invalid ISBN format")

    expected_checksum = calculate_checksum(parts)
    current_checksum = int(parts[9]) if parts[9] != 'X' else 10

    if expected_checksum == current_checksum:
        return "Right"
    else:
        corrected_parts = list(parts)
        corrected_parts[9] = 'X' if expected_checksum == 10 else str(expected_checksum)
        return '-'.join(''.join(corrected_parts[i:i+5]) for i in range(0, 10, 5))

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Count the number of chatting pairs that can be separated by adding a horizontal or vertical aisle
    horizontal_seps = [0] * (M + 1)
    vertical_seps = [0] * (N + 1)

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Yi == Qi:
            if Xi < Pi:
                horizontal_seps[Yi] += 1
            else:
                horizontal_seps[Qi] += 1
        elif Xi == Pi:
            if Yi < Qi:
                vertical_seps[Xi] += 1
            else:
                vertical_seps[Yi] += 1

    # Find the K most effective horizontal positions
    horizontal_positions = sorted(range(1, M + 1), key=lambda x: -horizontal_seps[x])[:K]

    # Find the L most effective vertical positions
    vertical_positions = sorted(range(1, N + 1), key=lambda x: -vertical_seps[x])[:L]

    # Convert the positions to space-separated strings
    horizontal_str = ' '.join(map(str, horizontal_positions))
    vertical_str = ' '.join(map(str, vertical_positions))

    return (horizontal_str, vertical_str)

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Initialize counters for each possible row and column aisle positions
    row_aisle_counts = [0] * M
    col_aisle_counts = [0] * N

    # Count how many chatting pairs can be separated by adding a row aisle at each position
    for (X1, Y1, X2, Y2) in chatting_pairs:
        if X1 == X2:
            row_aisle_counts[X1 - 1] += 1

    # Count how many chatting pairs can be separated by adding a column aisle at each position
    for (X1, Y1, X2, Y2) in chatting_pairs:
        if Y1 == Y2:
            col_aisle_counts[Y1 - 1] += 1

    # Find the K most effective row aisle positions to separate the most chatting pairs
    top_row_aisles = sorted(range(M), key=lambda i: -row_aisle_counts[i])[:K]
    top_row_aisles = [str(i + 1) for i in top_row_aisles]

    # Find the L most effective column aisle positions to separate the most chatting pairs
    top_col_aisles = sorted(range(N), key=lambda i: -col_aisle_counts[i])[:L]
    top_col_aisles = [str(i + 1) for i in top_col_aisles]

    # Return the optimal row and column indices for the aisles
    return ' '.join(top_row_aisles), ' '.join(top_col_aisles)

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Initialize variables to store the counts of separated chatting pairs
    row_separations = [0] * M
    col_separations = [0] * N

    # Calculate the number of chatting pairs that can be separated by adding an aisle at each possible position
    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi:  # Chatting pair is in the same row
            if Yi < Qi:
                row_separations[Xi - 1] += 1
            else:
                row_separations[Xi] += 1
        elif Yi == Qi:  # Chatting pair is in the same column
            if Xi < Pi:
                col_separations[Yi - 1] += 1
            else:
                col_separations[Yi] += 1

    # Sort the possible row and column aisle positions by the number of separating potential chatting pairs in descending order
    row_sorted_indices = sorted(range(M), key=lambda i: row_separations[i], reverse=True)
    col_sorted_indices = sorted(range(N), key=lambda i: col_separations[i], reverse=True)

    # Select the top K rows and L columns for aisles
    selected_rows = [str(i + 1) for i in row_sorted_indices[:K]]
    selected_cols = [str(i + 1) for i in col_sorted_indices[:L]]

    return ' '.join(selected_rows), ' '.join(selected_cols)

def count_passing_ways(n: int, m: int) -> int:
    if not isinstance(n, int) or not isinstance(m, int):
        raise ValueError("Both n and m must be integers.")
    if n < 1 or m < 0:
        raise ValueError("n must be greater than 0 and m must be non-negative.")

    # Initialize a 2D array to store the number of ways to reach each student after m passes
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # There is 1 way to be at each student after 0 passes (doing nothing)
    for i in range(n):
        dp[0][i + 1] = 1

    # Fill the dp array
    for j in range(1, m + 1):
        for i in range(n):
            dp[j][(i - 1) % n + 1] += dp[j - 1][i + 1]
            dp[j][(i + 1) % n + 1] += dp[j - 1][i + 1]

    # The result is the number of ways to be back at the starting student after m passes
    return dp[m][1]

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input: n must be greater than 0 and m must be non-negative")

    # Initialize a 2D DP table where dp[i][j] represents the number of ways to pass the ball to the i-th student after j passes
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base case: There's one way to be at the starting student after 0 passes
    for i in range(n):
        dp[i][0] = 1

    # Fill the DP table
    for j in range(1, m + 1):
        dp[0][j] = dp[-1][j - 1]
        for i in range(1, n - 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i + 1][j - 1]
        dp[-1][j] = dp[0][j - 1]

    # The result is the number of ways to be at the starting student after m passes
    return dp[0][m]

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        return 0

    # Initialize a 2D list to store the number of ways to reach each student at each pass
    dp = [[0] * n for _ in range(m + 1)]

    # Base case: There is one way to be at the starting student with 0 passes
    dp[0][0] = 1

    # Fill the dp table
    for pass_num in range(1, m + 1):
        for student in range(n):
            dp[pass_num][student] = dp[pass_num - 1][(student - 1) % n] + dp[pass_num - 1][(student + 1) % n]

    # The result is the number of ways to be at the starting student after m passes
    return dp[m][0]

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("n must be a positive integer and m must be a non-negative integer")
    if n == 1:
        return 1 if m == 0 else 0
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = dp[0][1] = 1
    for i in range(1, n):
        dp[i][0] = dp[0][0] + dp[0][1]
        for j in range(1, m + 1):
            dp[i][j] = dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]
    return dp[0][m]

