def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if not items or m == 0 or n <= 0:
        return 0

    # Create a 2D array to store the maximum importance value for each budget
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill the dp array
    for i in range(1, m + 1):
        price, importance = items[i - 1]
        for j in range(1, n + 1):
            if price > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - price] + importance)

    return dp[m][n]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a list to store the maximum importance for each budget level
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the dp list from the back to avoid using the same item multiple times
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + importance)

    # The maximum importance value that can be achieved without exceeding the budget is stored in dp[n]
    return dp[n]

def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = (i + length) % n
            for k in range(i + 1, j + n):
                k %= n
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[0][(n - 1) % n]

def max_energy(beads):
    n = len(beads)
    if n == 1:
        return 0

    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k + 1][j] + beads[i] * beads[k] * beads[j])

