def max_energy(beads):
    n = len(beads)
    if n < 3:
        # At least 3 beads are needed to form a valid merge
        return 0

    # Create a 2D array to store the maximum energy
    dp = [[0] * n for _ in range(n)]

    # Iterate over the length of the subsequence
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                if k == i:
                    dp[i][j] = max(dp[i][j], beads[i] * beads[k + 1] * beads[j])
                elif k + 1 == j:
                    dp[i][j] = max(dp[i][j], beads[j] * beads[i] * beads[k])
                else:
                    dp[i][j] = max(dp[i][j], dp[i][k] + dp[k + 1][j] + beads[i] * beads[k + 1] * beads[j])

    return dp[0][n - 1]

def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0  # Not enough beads to merge

    # Add the first bead as the last bead to handle the circular nature
    beads.extend(beads[:1])

    # Initialize the DP table
    dp = [[0] * (n + 2) for _ in range(n + 2)]

    # Fill the DP table
    for length in range(3, n + 2):
        for i in range(n + 2 - length):
            j = i + length
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[0][n + 1]

