def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        if i == 0:
            term = str(abs(coeff)) if abs(coeff) != 1 else ''
        elif i == 1:
            term = str(abs(coeff)) + 'x' if abs(coeff) != 1 else 'x'
        else:
            term = str(abs(coeff)) + 'x^' + str(i) if abs(coeff) != 1 else 'x^' + str(i)
        if coeff < 0:
            term = '-' + term
        elif terms:
            term = '+' + term
        terms.append(term)
    return ''.join(terms)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for degree in range(n, -1, -1):
        coeff = coeffs[n - degree]
        if coeff == 0:
            continue
        sign = '+' if coeff > 0 else '-'
        if abs(coeff) != 1 or degree == 0:
            coeff_str = str(abs(coeff))
        else:
            coeff_str = ''
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''
        term = sign + coeff_str + var_str
        terms.append(term[1:] if terms and term.startswith('+') else term)
    return ''.join(terms)

