def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        var_part = ''
        if i == 0:
            var_part = ''
        elif i == 1:
            var_part = 'x'
        else:
            var_part = f'x^{i}'

        if coeff == 1:
            if i == 1:
                term = var_part
            else:
                term = f'x^{i}'
        elif coeff == -1:
            if i == 1:
                term = f'-{var_part}'
            else:
                term = f'-x^{i}'
        else:
            term = f'{coeff}{var_part}'

        terms.append(term)

    return '-'.join(terms).replace('-x', '-1x')

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff != 0:
            if i == 0:
                term = str(abs(coeff))
            elif i == 1:
                term = f"{coeff}x" if coeff != 1 else "x"
            else:
                term = f"{coeff}x^{i}" if coeff != 1 else f"x^{i}"
            terms.append(term if coeff > 0 else "-" + term[1:])
    return "".join(terms) if terms else "0"

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) < 26:
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

