def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i

    return n

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    # Check for smallest prime factor 2
    if n % 2 == 0:
        return n // 2

    # Check for odd factors from 3 onwards
    factor = 3
    while factor * factor <= n:
        if n % factor == 0:
            return n // factor
        factor += 2

    # If no factors found, n itself is a prime number
    return n

def largest_prime_factor(n: int) -> int:
    # Check if the input number is less than 2
    if n < 2:
        raise ValueError("Input must be a positive integer greater than 1")

    # Iterate through potential factors starting from the smallest prime (2)
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            # If a factor is found, return the division of n by this factor
            return n // i

    # If no factors are found up to the square root of n, then n itself is a prime number
    # and is returned as the largest prime factor
    return n

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    # Start checking from the smallest prime number
    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            # Return the larger of the two factors
            return n // factor
        factor += 1

    # If no factors found, n is a prime number itself
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or k > n:
        return 0
    return count_partitions_helper(n, k, x, 0)

def count_partitions_helper(n: int, k: int, x: int, start: int) -> int:
    if k == 1:
        return 1 if n >= x else 0
    count = 0
    for i in range(start, n - k * x + 1):
        count += count_partitions_helper(n - i, k - 1, x, i + 1)
    return count

