def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    # Create a set of direct statements about guilt or innocence
    direct_statements = set()
    for participant, stmts in statements.items():
        for stmt in stmts:
            if stmt.startswith("I am guilty.") or stmt.startswith("I am innocent."):
                direct_statements.add(stmt.split()[2] if stmt.startswith("I am guilty.") else participant)

    # Check for consistency with the given scenario
    if scenario in liar_count:
        # If the scenario is a liar, their statements should not all align with the "truthful" statements
        if all(stmt in direct_statements for stmt in statements[scenario]):
            return False
    else:
        # If the scenario is not a liar, their statements should all align with the "truthful" statements
        if not any(stmt in direct_statements for stmt in statements[scenario]):
            return False

    # Ensure no statements about the day of the week cause inconsistency
    for stmt in direct_statements:
        if stmt in days_of_week:
            return False

    return True

