def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0 or not herbs:
        raise ValueError("Invalid input values")

    # Initialize the dp array where dp[i][j] represents the max value
    # that can be achieved with the first i herbs and j time
    dp = [[0 for _ in range(T + 1)] for _ in range(M + 1)]

    # Fill the dp array
    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        for j in range(1, T + 1):
            if time <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - time] + value)
            else:
                dp[i][j] = dp[i - 1][j]

    # The answer is in dp[M][T]
    return dp[M][T]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Edge case: if there are no herbs or no time, the maximum value is 0
    if M == 0 or T == 0:
        return 0

    # Initialize a list to store the maximum value for each time limit from 0 to T
    dp = [0] * (T + 1)

    # Iterate over each herb
    for time, value in herbs:
        # Update the dp array from the back to avoid overwriting values that are still needed
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    # The maximum value for the given time limit T will be stored in dp[T]
    return dp[T]

