    dp = [False] * (V + 1)
    dp[0] = True  # Base case: zero volume can always be achieved

    # Iterate over each item
    for volume in volumes:
        # Update the DP array from back to front to avoid using the same item multiple times
        for v in range(V, volume - 1, -1):
            if dp[v - volume]:
                dp[v] = True

    # Find the maximum volume that can be occupied
    max_occupied_volume = 0
    for v in range(V, -1, -1):
