    peak = -1
    for i in range(1, n - 1):
        if heights[i - 1] < heights[i] and heights[i] > heights[i + 1]:
            peak = i
            break

    if peak == -1:
        return n  # No valid peak found, all students need to leave

    # Calculate the length of the increasing subsequence before the peak
    increase = 1
    for i in range(peak - 1, -1, -1):
        if heights[i] < heights[i + 1]:
            increase += 1
        else:
            break

    # Calculate the length of the decreasing subsequence after the peak
    decrease = 1
    for i in range(peak + 1, n):
        if heights[i] < heights[i - 1]:
            decrease += 1
        else:
            break

    # The minimum number of students to leave is the total length minus the length of the valid choir
    return n - (increase + decrease - 1)

